def top_transform(P,axis=8):
 Q={p for p in P if p[1]==axis}
 for sel,dc in [([p for p in P if p[1]<axis],None),([p for p in P if p[1]>axis],None)]:
  if not sel:continue
  dr=-min(r for r,c in sel)
  dcol=-min(c for r,c in sel) if sel[0][1]<axis else 17-max(c for r,c in sel)
  Q.update((r+dr,c+dcol) for r,c in sel)
 return Q
def right_transform(P,axis=8):
 Q={p for p in P if p[0]==axis}
 for sel in [[p for p in P if p[0]<axis],[p for p in P if p[0]>axis]]:
  if not sel:continue
  dr=-min(r for r,c in sel) if sel[0][0]<axis else 17-max(r for r,c in sel)
  dc=17-max(c for r,c in sel)
  Q.update((r+dr,c+dc) for r,c in sel)
 return Q
